import React, { useState, useEffect } from 'react';
import { 
  Card, 
  Table, 
  Tag, 
  Button, 
  Space, 
  Select, 
  DatePicker, 
  Input, 
  Modal, 
  Form, 
  message,
  Typography,
  Descriptions,
  Alert
} from 'antd';
import { 
  ExclamationCircleOutlined, 
  CheckCircleOutlined, 
  ReloadOutlined,
  SearchOutlined,
  FilterOutlined
} from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import { apiRequest } from '../api';

const { Title } = Typography;
const { Option } = Select;
const { TextArea } = Input;

interface SecurityEvent {
  id: string;
  event_time: string;
  event_type: string;
  alert_level: string;
  title: string;
  description: string;
  resolved: boolean;
  resolved_at?: string;
}

const SecurityEvents: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [events, setEvents] = useState<SecurityEvent[]>([]);
  const [selectedEvent, setSelectedEvent] = useState<SecurityEvent | null>(null);
  const [resolveModalVisible, setResolveModalVisible] = useState(false);
  const [filters, setFilters] = useState({
    alert_level: undefined as string | undefined,
    resolved: undefined as boolean | undefined,
  });
  const navigate = useNavigate();
  const [form] = Form.useForm();

  const fetchEvents = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (filters.alert_level) params.append('alert_level', filters.alert_level);
      if (filters.resolved !== undefined) params.append('resolved', filters.resolved.toString());
      
      const response = await apiRequest(`/api/security/events?${params.toString()}`, 'GET');
      setEvents(response.events || []);
    } catch (err: any) {
      message.error('Ошибка загрузки событий: ' + (err.message || 'Неизвестная ошибка'));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEvents();
  }, [filters]);

  const handleResolveEvent = async (values: { resolution_notes: string }) => {
    if (!selectedEvent) return;

    try {
      await apiRequest(`/api/security/events/${selectedEvent.id}/resolve`, 'POST', {
        resolution_notes: values.resolution_notes
      });
      message.success('Событие успешно разрешено');
      setResolveModalVisible(false);
      setSelectedEvent(null);
      form.resetFields();
      fetchEvents();
    } catch (err: any) {
      message.error('Ошибка разрешения события: ' + (err.message || 'Неизвестная ошибка'));
    }
  };

  const getAlertLevelColor = (level: string) => {
    switch (level.toLowerCase()) {
      case 'info': return 'blue';
      case 'warning': return 'orange';
      case 'critical': return 'red';
      case 'emergency': return 'red';
      default: return 'default';
    }
  };

  const columns = [
    {
      title: 'Время',
      dataIndex: 'event_time',
      key: 'event_time',
      render: (time: string) => new Date(time).toLocaleString('ru-RU'),
      width: 150,
      sorter: (a: SecurityEvent, b: SecurityEvent) => 
        new Date(a.event_time).getTime() - new Date(b.event_time).getTime(),
    },
    {
      title: 'Тип',
      dataIndex: 'event_type',
      key: 'event_type',
      width: 120,
    },
    {
      title: 'Уровень',
      dataIndex: 'alert_level',
      key: 'alert_level',
      render: (level: string) => (
        <Tag color={getAlertLevelColor(level)}>
          {level.toUpperCase()}
        </Tag>
      ),
      width: 100,
      filters: [
        { text: 'INFO', value: 'INFO' },
        { text: 'WARNING', value: 'WARNING' },
        { text: 'CRITICAL', value: 'CRITICAL' },
        { text: 'EMERGENCY', value: 'EMERGENCY' },
      ],
      onFilter: (value: any, record: SecurityEvent) => record.alert_level === value,
    },
    {
      title: 'Событие',
      dataIndex: 'title',
      key: 'title',
    },
    {
      title: 'Статус',
      dataIndex: 'resolved',
      key: 'resolved',
      render: (resolved: boolean, record: SecurityEvent) => (
        <Space>
          {resolved ? (
            <Tag color="green" icon={<CheckCircleOutlined />}>
              Разрешено
            </Tag>
          ) : (
            <Tag color="red" icon={<ExclamationCircleOutlined />}>
              Активно
            </Tag>
          )}
      {resolved && record.resolved_at && (
            <span style={{ fontSize: 12 }}>
              {new Date(record.resolved_at).toLocaleString('ru-RU')}
            </span>
          )}
        </Space>
      ),
      width: 150,
      filters: [
        { text: 'Активные', value: false },
        { text: 'Разрешенные', value: true },
      ],
      onFilter: (value: any, record: SecurityEvent) => record.resolved === value,
    },
    {
      title: 'Действия',
      key: 'actions',
      render: (_, record: SecurityEvent) => (
        <Space>
          <Button 
            size="small" 
            onClick={() => setSelectedEvent(record)}
          >
            Детали
          </Button>
          {!record.resolved && (
            <Button 
              size="small" 
              type="primary"
              onClick={() => {
                setSelectedEvent(record);
                setResolveModalVisible(true);
              }}
            >
              Разрешить
            </Button>
          )}
        </Space>
      ),
      width: 120,
    },
  ];

  return (
    <div style={{ padding: 'var(--sp-spacing-sm)', boxSizing: 'border-box', maxWidth: '100%' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 'var(--sp-spacing-sm)' }}>
        <Title level={2}>
          <ExclamationCircleOutlined style={{ marginRight: 8 }} />
          События безопасности
        </Title>
        <Space>
          <Button 
            onClick={() => navigate('/security')}
          >
            Назад к панели
          </Button>
          <Button 
            icon={<ReloadOutlined />} 
            onClick={fetchEvents}
            loading={loading}
          >
            Обновить
          </Button>
        </Space>
      </div>

      {/* Фильтры */}
      <Card size="small" style={{ marginBottom: 'var(--sp-spacing-sm)' }}>
        <Space wrap>
          <Select
            placeholder="Уровень оповещения"
            allowClear
            style={{ width: 150 }}
            value={filters.alert_level}
            onChange={(value) => setFilters(prev => ({ ...prev, alert_level: value }))}
          >
            <Option value="INFO">INFO</Option>
            <Option value="WARNING">WARNING</Option>
            <Option value="CRITICAL">CRITICAL</Option>
            <Option value="EMERGENCY">EMERGENCY</Option>
          </Select>
          <Select
            placeholder="Статус"
            allowClear
            style={{ width: 120 }}
            value={filters.resolved}
            onChange={(value) => setFilters(prev => ({ ...prev, resolved: value }))}
          >
            <Option value={false}>Активные</Option>
            <Option value={true}>Разрешенные</Option>
          </Select>
        </Space>
      </Card>

      {/* Таблица событий */}
      <Card>
        <Table
          dataSource={events}
          columns={columns}
          rowKey="id"
          loading={loading}
          pagination={{
            pageSize: 20,
            showSizeChanger: true,
            showQuickJumper: true,
            showTotal: (total) => `Всего событий: ${total}`,
          }}
          scroll={{ x: 800 }}
        />
      </Card>

      {/* Модальное окно с деталями события */}
      <Modal
        title="Детали события"
        open={!!selectedEvent && !resolveModalVisible}
        onCancel={() => setSelectedEvent(null)}
        footer={[
          <Button key="close" onClick={() => setSelectedEvent(null)}>
            Закрыть
          </Button>,
          !selectedEvent?.resolved && (
            <Button 
              key="resolve" 
              type="primary"
              onClick={() => setResolveModalVisible(true)}
            >
              Разрешить событие
            </Button>
          ),
        ].filter(Boolean)}
        width={600}
      >
        {selectedEvent && (
          <Descriptions column={1} bordered size="small">
            <Descriptions.Item label="ID">
              {selectedEvent.id}
            </Descriptions.Item>
            <Descriptions.Item label="Время">
              {new Date(selectedEvent.event_time).toLocaleString('ru-RU')}
            </Descriptions.Item>
            <Descriptions.Item label="Тип">
              {selectedEvent.event_type}
            </Descriptions.Item>
            <Descriptions.Item label="Уровень">
              <Tag color={getAlertLevelColor(selectedEvent.alert_level)}>
                {selectedEvent.alert_level}
              </Tag>
            </Descriptions.Item>
            <Descriptions.Item label="Заголовок">
              {selectedEvent.title}
            </Descriptions.Item>
            <Descriptions.Item label="Описание">
              {selectedEvent.description}
            </Descriptions.Item>
            <Descriptions.Item label="Статус">
              {selectedEvent.resolved ? (
                <Tag color="green" icon={<CheckCircleOutlined />}>
                  Разрешено {selectedEvent.resolved_at && 
                    `(${new Date(selectedEvent.resolved_at).toLocaleString('ru-RU')})`
                  }
                </Tag>
              ) : (
                <Tag color="red" icon={<ExclamationCircleOutlined />}>
                  Активно
                </Tag>
              )}
            </Descriptions.Item>
          </Descriptions>
        )}
      </Modal>

      {/* Модальное окно разрешения события */}
      <Modal
        title="Разрешить событие безопасности"
        open={resolveModalVisible}
        onCancel={() => {
          setResolveModalVisible(false);
          form.resetFields();
        }}
        onOk={() => form.submit()}
        okText="Разрешить"
        cancelText="Отмена"
      >
        <Alert
          message="Внимание"
          description="Разрешение события означает, что проблема устранена и не требует дальнейшего внимания."
          type="warning"
          showIcon
          style={{ marginBottom: 'var(--sp-spacing-sm)' }}
        />
        
        <Form
          form={form}
          layout="vertical"
          onFinish={handleResolveEvent}
        >
          <Form.Item
            label="Комментарий к разрешению"
            name="resolution_notes"
            rules={[
              { required: true, message: 'Пожалуйста, укажите причину разрешения' },
              { min: 10, message: 'Комментарий должен содержать минимум 10 символов' }
            ]}
          >
            <TextArea
              rows={4}
              placeholder="Опишите, как была решена проблема или почему событие больше не актуально..."
            />
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
};

export default SecurityEvents;
